import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"08 | 数字证书：攻击者可以伪造证书吗？","description":"","frontmatter":{},"headers":[{"level":2,"title":"证书","slug":"证书","link":"#证书","children":[{"level":3,"title":"CA 证书颁发机构","slug":"ca-证书颁发机构","link":"#ca-证书颁发机构","children":[]},{"level":3,"title":"根证书","slug":"根证书","link":"#根证书","children":[]}]},{"level":2,"title":"信任链","slug":"信任链","link":"#信任链","children":[{"level":3,"title":"证书信任链的不正确回溯","slug":"证书信任链的不正确回溯","link":"#证书信任链的不正确回溯","children":[]}]},{"level":2,"title":"案例实战","slug":"案例实战","link":"#案例实战","children":[{"level":3,"title":"Let’s Encrypt","slug":"let-s-encrypt","link":"#let-s-encrypt","children":[]},{"level":3,"title":"中间人攻击（MITM）","slug":"中间人攻击-mitm","link":"#中间人攻击-mitm","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Web漏洞挖掘实战/08｜数字证书：攻击者可以伪造证书吗？.md","filePath":"Web漏洞挖掘实战/08｜数字证书：攻击者可以伪造证书吗？.md","lastUpdated":1795536081000}'),s={name:"Web漏洞挖掘实战/08｜数字证书：攻击者可以伪造证书吗？.md"};function p(l,e,r,E,o,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="_08-数字证书-攻击者可以伪造证书吗" tabindex="-1">08 | 数字证书：攻击者可以伪造证书吗？ <a class="header-anchor" href="#_08-数字证书-攻击者可以伪造证书吗" aria-label="Permalink to &quot;08 | 数字证书：攻击者可以伪造证书吗？&quot;">​</a></h1><p>你好，我是王昊天。</p><p>我们都知道，www.baidu.com 之所以能够访问 Baidu，是因为 DNS 在解析 www.baidu.com这个记录的时候将 IP 地址指向了 Baidu 的服务器集群，通过 DNS 协议我们可以找到正确的服务器地址。</p><p>很多时候，我们在连接网络的时候没有手动设置 DNS 服务器地址，这时我们采用的就是网关统一的默认 DNS 服务器。如果网关的 DNS 被黑客入侵，并且黑客将 www.baidu.com 指向了自己构建的恶意网站，用户就会访问错误的站点，同时可能遭遇黑客的进一步控制。</p><p>那么问题来了，我们该如何判断正在访问的站点的真实性呢？</p><p>答案就是互联网证书体系，而证书体系的有效性就依赖于信任链，这就是这节课我们要一起研究的内容。</p><h2 id="证书" tabindex="-1">证书 <a class="header-anchor" href="#证书" aria-label="Permalink to &quot;证书&quot;">​</a></h2><p>我们平时在网络上常说的证书全称叫数字证书，它是一种基于公钥认证体系的电子文件，用于证明公钥持有者的身份。</p><p>一般在证书中会包含以下几类信息：</p><ul><li><p>公钥信息</p></li><li><p>拥有者身份信息</p></li><li><p>数字证书认证机构对该文件的数字签名</p></li></ul><p>证书持有者通过该文件（证书），即可向系统或者其他用户证明身份，从而获得对方信任并授权使用某些敏感服务。</p><p>这里我们使用 Mac 系统，通过 launchpad -&gt; 其他 -&gt; 钥匙串访问 -&gt; 系统根证书，可以查看目前系统内部预置的根证书。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/1.png" alt=""></a></p><p>简单来说，认证机构用自己的私钥对需要认证的人或组织的公钥施加数字签名并生成证书，即证书的本质就是对公钥施加数字签名。</p><h3 id="ca-证书颁发机构" tabindex="-1">CA 证书颁发机构 <a class="header-anchor" href="#ca-证书颁发机构" aria-label="Permalink to &quot;CA 证书颁发机构&quot;">​</a></h3><p>CA（Certificate Authority）是证书的签发机构，它是公钥基础设施的核心，负责签发证书、认证证书、管理证书。</p><p>作为互联网信息服务商，它是如何获得证书的呢？</p><p>首先，服务商要先向 CA 提出申请，这一流程往往是线下的商务流程，主要任务是确认现实生活中各种资料；接下来，CA 会确认服务商的身份，若通过审核则为服务商颁发公钥，并将公钥信息与用户身份信息绑定；最后，CA 为绑定身份的公钥信息进行签名，签名结果即是证书，返还给申请者。根据这个证书颁发流程，我们可以发现 CA 也是拥有证书申请者的公钥以及私钥的。</p><p>CA 通过证书赋予了服务商信任，那么网上的公众用户又该如何信任 CA 以及获得证书的服务商呢？答案是签名验证。对于 CA，用户可以通过验证 CA 的签名来证明它的合法性（签名的验证过程实际上是使用公钥对私钥加密的数据段进行解密的过程）；而对于服务商，用户则可以选择使用 CA 的公钥对服务商证书进行签名验证，一旦验证通过，即证明了证书的有效性。</p><h3 id="根证书" tabindex="-1">根证书 <a class="header-anchor" href="#根证书" aria-label="Permalink to &quot;根证书&quot;">​</a></h3><p>自古以来，有一个千古难题 —— 鸡生蛋，蛋生鸡，那么先有鸡还是先有蛋呢？</p><p>不知道你有没有发现，我们刚刚似乎遗漏了什么至关重要的东西——用户是如何验证 CA 签名的呢？为了解决这个问题，这里我们要引入一个新的概念——根证书（root certificate）。</p><p>在密码学和计算机安全领域，根证书是属于“根证书颁发机构”的公钥证书，在公钥基础设施体系中，它是信任链的起点，是一切安全信任的基石，通常来自公认可靠的政府机关、证书颁发机构以及非营利性组织。根证书在互联网领域获得广泛认可，通常被预先安装在操作系统、浏览器等软件中。</p><p>在时效性上，由于根证书的颁发和部署流程都非常复杂耗时，需要包括行政人员及机构法人身份的核准，所以一张根证书有效期可以长达 20 年以上。</p><p>一些大企业会自己研发及部署很多内部应用，他们会在内部电脑安装企业自签的根证书，以支持内部网络的企业级软件，但是由于这些证书未被广泛认可，因此只在企业内部应用环境可用。</p><h2 id="信任链" tabindex="-1">信任链 <a class="header-anchor" href="#信任链" aria-label="Permalink to &quot;信任链&quot;">​</a></h2><p>想要了解什么是信任链，我们还要从根证书的签发说起。</p><p>由于终端直接面向用户的服务商数量巨大，根证书签发的效率又比较低，如果只有数量有限的根证书机构签发证书，将会严重影响证书授权数量。为了解决这一问题，中间商的身份被引入进来。中间商只要持有根证书机构签发的中介证书，就有权给服务商授权证书。这里服务商获得的证书叫终端实体证书。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/2.png" alt=""></a></p><p>当互联网用户访问一个网站时，浏览器会执行认证路径验证算法，使用网站所提供的电子证书去对应系统预安装的根证书，通过验证两者是否匹配来判断从根证书到终端节点的路径是否为一条有效的信任链。如下图所示，整个信任链的结构是一个以根证书为顶层的树状结构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/3.png" alt=""></a></p><h3 id="证书信任链的不正确回溯" tabindex="-1">证书信任链的不正确回溯 <a class="header-anchor" href="#证书信任链的不正确回溯" aria-label="Permalink to &quot;证书信任链的不正确回溯&quot;">​</a></h3><p>在 coding 过程中，当我们需要对证书进行验证时，可能会直接调用证书验证函数来获取验证结果，但是却没有对证书信任链进行有效地回溯，这就可能导致错误的信任关系的产生。</p><p>简单来说，从证书验证过程获取的信任是从信任链中继承下来的，而信任链的终点是一个可信的机构实体。在通常的工作场景中，这条信任链会经过多个实体，这些实体会为信任链中的下一个实体做担保，信任链的起点就是终端用户访问的目标。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/4.png" alt=""></a></p><p>在用户获取了访问目标证书的情况下，如果想要建立信任关系，只检查第一层信任链是不够的，你需要对完整的信任链进行检查。</p><p>举例来说，以下这些场景都会导致信任链断裂：</p><ul><li><p>信任链中任意一个非根节点的证书是自签发的（self-signed）；</p></li><li><p>没有完成整个信任链中每个节点的检查；</p></li><li><p>信任链中的某个节点证书缺失一些基础信息或者额外的重要扩展信息；</p></li><li><p>信任链中上层节点证书失效或者被攻击者窃取。</p></li></ul><p>示例代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>...</span></span>
<span class="line"><span>cert = ssl_get_peer_certificate(ssl);</span></span>
<span class="line"><span>if( cert &amp;&amp; host )</span></span>
<span class="line"><span>   foo = ssl_get_verify_result(ssl);</span></span>
<span class="line"><span>if( X509_V_OK == foo || X509_V_ERR_SELF_SIGNED_CERT_IN_CHAIN == foo)</span></span>
<span class="line"><span>   return 0;</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>这是从网络上 copy-paste 的一段代码，你可以找到上述代码有什么安全隐患吗？</p><p>这段代码的安全隐患，主要是由于对证书验证过程理解不深刻导致的。代码作者直接使用了网络上的代码片段而没有仔细检查逻辑，使得这段代码允许了自签名证书的使用，因此并未构建有效地信任链，这就可能引发 DNS 污染或者中间人攻击等安全风险。</p><h2 id="案例实战" tabindex="-1">案例实战 <a class="header-anchor" href="#案例实战" aria-label="Permalink to &quot;案例实战&quot;">​</a></h2><h3 id="let-s-encrypt" tabindex="-1">Let’s Encrypt <a class="header-anchor" href="#let-s-encrypt" aria-label="Permalink to &quot;Let’s Encrypt&quot;">​</a></h3><p>如果我们有一个正在运营的 Web 应用，应该如何为这个 Web 应用配置一个 SSL 证书呢？</p><p>这里我们来通过MiTuan了解一下业内的 SSL 证书生态及使用方法。</p><p>首先，通过浏览器访问MiTuan主页，可以发现浏览器栏左侧有一个小锁的标志，这个锁的标志意味着该用户与该站点的通信受到保护，通信数据对于第三方是不可见的。</p><p>接下来，点击小锁并进入安全页，可以看到目前的证书是有效的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/5.png" alt=""></a></p><p>再接下来通过选择证书有效这个选项，我们可以打开证书信息：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/6.png" alt=""></a></p><p>可以看到 mituan.zone 的证书由 Let’s Encrypt 签发；它的上级信任链节点是 R3 证书，R3 证书所处的节点是一个中级证书颁发机构，R3 证书由 ISRG 根证书签发；ISRG 根证书属于Internet Security Research Group，该机构是一个根证书颁发机构。</p><p>关于 Let’s Encrypt，它是一个非营利性的数字证书认证机构，旨在以自动化流程代替手动创建和安装证书，可以为网站提供免费的传输层安全协议（TLS）证书。Let’s Encrypt 由 ISRG（互联网安全研究小组）提供服务支撑。</p><p>从 mituan.zone 的访问来看，Let’s Encrypt 的证书是有效的，那么为什么 Let’s Encrypt 签发的证书能够被识别为安全呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/7.png" alt=""></a></p><p>在技术实现上，Let’s Encrypt 有一个由 IdenTrust 签名的根证书，该根证书在签署了两个子证书后离线储存，两个子证书分别用于签发请求和本地备份。而 IdenTrust 的 CA 根证书已经被广泛地预置在大部分浏览器中，因此 Let’s Encrypt 签发的证书可以直接被识别，用户甚至不需要在本地存放 ISRG 的根证书。</p><h3 id="中间人攻击-mitm" tabindex="-1">中间人攻击（MITM） <a class="header-anchor" href="#中间人攻击-mitm" aria-label="Permalink to &quot;中间人攻击（MITM）&quot;">​</a></h3><p>无论是开发中调试，还是安全项目中的模拟渗透，我们都会遇见一些场景需要调试 Web 应用的网络交互过程，这种调试工作一般是通过 Proxy 工具来完成的，在一般情况下 Proxy 工具都可以很好地完成任务，但是当 TLS 证书存在的情况下，事情会出现一些新的变化。</p><p>仍然以 mituan.zone 为例，此时我们希望在本地 proxy 工具中调试登录过程，让我们来试试看：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/8.png" alt=""></a></p><p>我使用的是 Mac OS 上面的 Charles（Web Debugging Proxy）应用，可以看到打开 Charles并启动代理流量捕获后，我们并没有成功获取到 mituan.zone 的通信内容，得到的是一个失败的说明——由于证书问题导致客户端 SSL 握手失败。</p><p>这是一个非常有意思的地方，上面失败说明中的客户端就是我们访问 mituan.zone 的浏览器。要知道，浏览器可是在我们自己手里，要不要信任对方还不是我们说了算？你说它可信，它就可信！但问题是，浏览器说的不可信指的是谁呢？</p><p>想要知道浏览器所指的 certificate_unknown(46) 错误究竟指谁，就要了解 Charles 的技术实现原理。实际上，Charles 会自己启动一个 Porxy，然后将 Browser 的访问流量导向 Proxy，最后再从 Proxy 中将流量发到目标站点，通过这样的方式实现对于通信内容的捕获。</p><p>了解了实现原理，答案就很清晰了：浏览器所说的证书不可信，指的就是 Charles 的证书。</p><p>那我们接下来只需要将 Charles 的证书加载到系统内并设置信任即可：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/9.png" alt=""></a></p><p>完成 Charles 的证书信任设置后，我们再次尝试捕获通信内容：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/10.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/08/11.png" alt=""></a></p><p>可以看到我们已经能够对 TLS 加密的 HTTP 请求进行内容分析了，这一过程在安全领域我们就称为——中间人攻击。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课我们学习了如何使用加密知识构建互联网安全信任体系。</p><p>在互联网出现的早期，有一句流传很广的话——“在互联网上，没人知道你是一条狗”。这句话的背后意味着互联网身份的不可信，这种特性或许在匿名社交上有很大优势，但是在互联网商业服务领域却不可接受。来自互联网的终端用户需要一种方式，使他们能够确定访问的目标主体是真正的服务商，而不是骗子伪造的站点。</p><p>为了构建互联网信任体系，数字证书应运而生。它是一种基于公钥认证体系的电子文件，包含服务商的身份信息、公钥信息以及数字签名。这一体系的核心是证书颁发机构，也就是我们常说的 CA。如果说 CA 是流程层面的核心，那么根证书则是技术层面的核心，通过信任链的层层传导，才能够完成整个互联网信任体系的搭建。</p><p>在本节课的实战案例部分，我们首先一起体验了 TLS 证书的检查以及申请过程，这些知识可以帮助你快速构建起安全的 Web 应用；接下来以 Web 调试需求为场景，我们又一起探索了Web 调试工具的技术原理，以及 MITM（Man-In-The-Middle Attack，中间人攻击）的实现思路。</p><p>相信通过本节课程的学习，你可以对证书以及信任链有一个清晰、整体的理解。这些知识不仅在构建安全的 Web 应用领域会对你产生帮助，更会在加密体系加持的多种新兴技术领域让你快速成长。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你可以尝试通过 OpenSSL 来生成自己的 root CA 以及签发证书吗？</p><p>欢迎在评论区留下你的思考，我们下节课再见。</p>`,79)])])}const b=t(s,[["render",p]]);export{g as __pageData,b as default};
